-- 1. Remover variações antigas (aquelas vinculadas a produtos específicos)
DELETE FROM variationTypes WHERE productId IS NOT NULL;

-- 2. Remover opções órfãs (que não têm variationType associada)
DELETE FROM variationOptions WHERE variationTypeId NOT IN (SELECT id FROM variationTypes);

-- 3. Remover tabelas antigas de materiais, acabamentos e tipos de impressão
DELETE FROM materials;
DELETE FROM finishes;
DELETE FROM printingTypes;

